files=[('digits-studio-brand-kit.zip','Complete brand kit / ZIP'),('digits-studio-brand-guide.pdf','12-page brand guide / PDF'),('business-cards-print-proof.pdf','Business cards / print proof'),('letterhead-a4.pdf','A4 letterhead / PDF'),('proposal-cover-a4.pdf','Proposal cover / PDF'),('linkedin-cover.png','LinkedIn cover / PNG'),('social-square.png','Square launch post / PNG'),('whatsapp-qr.png','WhatsApp QR / PNG'),('launch-copy.md','English and Arabic launch copy'),('content-plan.csv','30-day content plan / CSV'),('email-signature.html','Email signature / HTML'),('contact.vcf','Ahmad’s contact card / vCard'),('brand-tokens.json','Design tokens / JSON'),('brand-tokens.css','Design tokens / CSS'),('logo-live-text.svg','Live-text wordmark alternative'),('strategy.md','Positioning and launch notes')]
